    while found < count:
        for d in unique_days:
            day_offset = week * 7 + d
            occ_start = day_offset * 1440 + start
            occ_end = day_offset * 1440 + end
            occurrences.append((day_offset, occ_start, occ_end))
            found += 1
            if found == count:
                break
        week += 1

    # Sort occurrences by day_offset then start time
    occurrences.sort()

    # Filter blackouts
    result = []
    for occ in occurrences:
        day_num, occ_s, occ_e = occ
